<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Sorting Visualizer</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    background: #1a1a2e;
    color: #eee;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 20px;
  }

  h1 {
    margin-bottom: 20px;
    font-size: 2em;
    background: linear-gradient(90deg, #e94560, #0f3460);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .controls {
    display: flex;
    gap: 12px;
    margin-bottom: 20px;
    flex-wrap: wrap;
    justify-content: center;
  }

  button {
    padding: 10px 24px;
    font-size: 1em;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.2s ease;
    font-weight: 600;
  }

  button:hover { transform: translateY(-2px); box-shadow: 0 4px 15px rgba(0,0,0,0.3); }
  button:active { transform: translateY(0); }

  #sort { background: #e94560; color: white; }
  #shuffle { background: #0f3460; color: white; }
  #reset { background: #533483; color: white; }

  #status {
    margin-bottom: 15px;
    font-size: 1.1em;
    min-height: 25px;
    color: #a0a0b0;
  }

  #bars {
    display: flex;
    align-items: flex-end;
    justify-content: center;
    gap: 2px;
    width: 100%;
    max-width: 900px;
    height: 400px;
    padding: 10px;
    background: #16213e;
    border-radius: 8px;
    border: 1px solid #0f3460;
  }

  .bar {
    flex: 1;
    min-width: 4px;
    max-width: 60px;
    background: linear-gradient(180deg, #e94560, #c23152);
    border-radius: 3px 3px 0 0;
    transition: height 0.1s ease, background 0.15s ease;
    position: relative;
  }

  .bar.comparing {
    background: linear-gradient(180deg, #ffd700, #ffaa00);
  }

  .bar.sorted {
    background: linear-gradient(180deg, #4ecca3, #2d9e7a);
  }

  .bar.swapping {
    background: linear-gradient(180deg, #ff6b6b, #ee5a5a);
  }
</style>
</head>
<body>
<h1>Sorting Visualizer</h1>
<div class="controls">
  <button id="sort">Sort Ascending</button>
  <button id="shuffle">Shuffle</button>
  <button id="reset">Reset</button>
</div>
<div id="status"></div>
<div id="bars"></div>

<script>
(function() {
  const barsContainer = document.getElementById('bars');
  const statusEl = document.getElementById('status');
  let currentArray = [];
  let sortState = null; // tracks bubble sort state for step-by-step execution
  let isSorted = true;

  function generateRandomArray(size) {
    const arr = [];
    for (let i = 0; i < size; i++) {
      arr.push(Math.floor(Math.random() * 95) + 5); // values 5-99
    }
    return arr;
  }

  function renderBars(highlightIndices = {}, sortedSet = new Set()) {
    barsContainer.innerHTML = '';
    const maxVal = Math.max(...currentArray, 1);

    currentArray.forEach((val, idx) => {
      const bar = document.createElement('div');
      bar.className = 'bar';
      const heightPct = (val / maxVal) * 95;
      bar.style.height = heightPct + '%';

      if (highlightIndices.comparing && highlightIndices.comparing.includes(idx)) {
        bar.classList.add('comparing');
      } else if (sortedSet.has(idx)) {
        bar.classList.add('sorted');
      }

      barsContainer.appendChild(bar);
    });
  }

  function initSortState() {
    sortState = {
      i: currentArray.length - 1,
      j: 0,
      phase: 'compare', // 'compare' or 'swap'
      done: false
    };
    isSorted = false;
  }

  function sortStep() {
    if (isSorted) return true;

    if (!sortState) {
      initSortState();
    }

    const n = currentArray.length;

    // Bubble sort implementation - one step at a time
    while (sortState.i > 0) {
      if (sortState.phase === 'compare') {
        if (sortState.j < sortState.i) {
          // Perform comparison - this is the "step"
          const prevI = sortState.i;
          const prevJ = sortState.j;

          sortState.j++;

          // Render with highlighting for visual feedback
          renderBars(
            { comparing: [prevJ, prevI] },
            new Set()
          );

          // Actually perform the comparison and swap if needed
          if (currentArray[prevJ - 1] > currentArray[prevI]) {
            const temp = currentArray[prevJ - 1];
            currentArray[prevJ - 1] = currentArray[prevI];
            currentArray[prevI] = temp;
            renderBars(
              { comparing: [prevJ - 1, prevI] },
              new Set()
            );
          }

          return false;
        } else {
          // Move to next iteration of outer loop
          sortState.i--;
          sortState.j = 0;
          sortState.phase = 'compare';
        }
      }
    }

    isSorted = true;
    renderBars({}, new Set(currentArray.keys()));

    if (sorted()) {
      statusEl.textContent = '✓ Array is sorted!';
      return true;
    }

    return false;
  }

  function sorted() {
    for (let i = 0; i < currentArray.length - 1; i++) {
      if (currentArray[i] > currentArray[i + 1]) {
        return false;
      }
    }
    return true;
  }

  // Public API
  window.viz = {
    array: function() {
      return [...currentArray];
    },

    setArray: function(a) {
      currentArray = [...a];
      sortState = null;
      isSorted = false;
      renderBars();

      if (sorted()) {
        isSorted = true;
        statusEl.textContent = '✓ Array is sorted!';
      } else {
        statusEl.textContent = '';
      }
    },

    sortStep: function() {
      return sortStep();
    },

    sorted: function() {
      return sorted();
    }
  };

  // Button handlers
  document.getElementById('sort').addEventListener('click', function() {
    if (!sorted()) {
      statusEl.textContent = 'Sorting...';
      // Run sortStep in animation loop for visual feedback
      const animateSort = () => {
        if (sorted()) {
          statusEl.textContent = '✓ Array is sorted!';
          return;
        }
        window.viz.sortStep();
        requestAnimationFrame(animateSort);
      };
      animateSort();
    } else {
      statusEl.textContent = 'Array already sorted.';
    }
  });

  document.getElementById('shuffle').addEventListener('click', function() {
    const size = currentArray.length || Math.floor(Math.random() * 20) + 15;
    if (currentArray.length === 0) {
      currentArray = generateRandomArray(size);
    } else {
      // Fisher-Yates shuffle
      for (let i = currentArray.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [currentArray[i], currentArray[j]] = [currentArray[j], currentArray[i]];
      }
    }
    sortState = null;
    isSorted = false;
    renderBars();
    statusEl.textContent = '';
  });

  document.getElementById('reset').addEventListener('click', function() {
    currentArray = [];
    sortState = null;
    isSorted = true;
    barsContainer.innerHTML = '';
    statusEl.textContent = 'Ready. Click Shuffle to start.';
  });

  // Initialize with a random array
  const initialSize = Math.min(Math.floor(window.innerWidth / 30), 40);
  currentArray = generateRandomArray(Math.max(initialSize, 15));
  renderBars();
})();
</script>
</body>
</html>
